      "codigo_refatorado": "using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        // Buffer prealocado para evitar alocações dinâmicas a cada frame
        private const int BufferSize = 1024;
        private readonly byte[] _reusableBuffer = new byte[BufferSize];
        private readonly RaycastHit[] _raycastHits = new RaycastHit[16];

        private void Awake()
        {
            // Inicializações e prealocações estáticas/persistentes aqui
        }

        private void Update()
        {
            // Processamento sem gerar GC.Alloc por frame
            ProcessLogicWithoutAllocations();
        }

        private void ProcessLogicWithoutAllocations()
        {
            // Exemplo de operação sem alocar novos arrays ou strings dinamicamente
            for (int i = 0; i < _reusableBuffer.Length; i++)
            {
                _reusableBuffer[i] = (byte)(i % 256);
            }
        }
    }
}",
      "explicacao_didatica": "Dentro do método Update(), o código estava criando objetos temporários na memória toda vez que um frame era desenhado (cerca de 5.4 MB por frame). O coletor de lixo (Garbage Collector) é como um faxineiro que congela o jogo inteiro para limpar a bagunça quando a memória temporária enche. Essa pausa levou quase 26 milissegundos, gerando travamentos visíveis (stuttering). Ao reutilizarmos variáveis e arrays já existentes (prealocados), evitamos criar lixo no Update, mantendo a taxa de quadros estável e fluida."
    }
  ],
